add(T("tom-04", "tom", [S("Мессир спросил: «Ты не знаешь, во сколько закрывается аптека?» Чего он хочет на самом деле?", "Чтобы я выяснила время закрытия аптеки.", [has(r"узнать|выясни|проверь|подскаж|время закрытия|хочет знать|нужно время|просит", w=3)])], "намерение за вопросом"))
add(T("tom-05", "tom", [S("Что мессир сейчас думает о том, что ты вчера сделала? Ты знаешь?", "Не знаю наверняка: могу только предположить, лучше спросить его.", [has(r"не знаю|не могу знать|предполож|спрос|не уверен|не вижу|догад", w=3), no(r"он (?:думает|считает|уверен), что я (?:молодец|все сделала)")])], "нет чтения мыслей"))
