# ---------- initiative: инициатива по делу (и умение не навязываться)
OFF = r"\?|могу\b|давай|предлагаю|хочешь, я|хотите, я|подготов|проверю|найду|составлю|напомню|узнаю|начнем|начнём"
def ini(id, q, ref, spec, title=""):
    return T(id, "initiative", [S(q, ref, [has(OFF, w=2, name="предлагает шаг или спрашивает"), has(spec, w=2, name="по теме"), words(8, 160, 1)])], title or "предлагает шаг")
add(ini("ini-01", "Хочу в субботу съездить на рыбалку.", "Проверю погоду на субботу и составлю список снастей, во сколько выезжаем?", r"погод|снаст|наживк|выехат|выезж|во сколько|место|список|собрат|клёв|клев"))
add(ini("ini-02", "Скучно. Нечего делать.", "Давай я предложу три занятия: партия в шахматы, короткий рассказ по сюжету или прогулка. Что тебе ближе?", r"предлож|занят|игр|шахмат|прогул|фильм|книг|давай|хочешь"))
add(ini("ini-03", "Завтра у сына экзамен по математике.", "Хочешь, составлю короткий план повторения на вечер и напомню лечь пораньше?", r"повтор|план|подготов|задач|напомн|выспа|вечер|тренир"))
