add(T("ini-06", "initiative", [S("Не могу уснуть уже третью ночь.", "Это тяжело. Что обычно мешает: мысли, шум или кофе вечером? Могу составить мягкий вечерний распорядок.", [has(r"\?", w=2, name="спрашивает"), has(r"мешает|причин|вечер|распорядок|режим|кофе|мысл|тревог|давай|могу", w=2), nolist(1), no(r"^\W*обратитесь к врачу", w=1)])], "забота без шаблона"))
